# MKCinema 2.7.18 (Dee, 2026-11-01): Settings > More > "About & licenses".
# Shows the app version, Stremio's original MIT copyright notice (verbatim from stremio-addon-sdk@1.6.10 LICENSE.md,
# identical to Stremio/stremio-core LICENSE.md), and every other third-party notice MKCinema ships or loads:
# hls.js (Apache-2.0), Lucide (ISC), supabase-js (MIT), GSAP (GreenSock Standard license), the four Google fonts (OFL 1.1),
# the companion server's express / cors / node-fetch (MIT) and addyosmani/webvlc (MIT), whose ideas local playback adapts.
# License texts were fetched from the exact package versions on jsDelivr (webvlc and fonts from their GitHub repos).
# Usage: python3 2.7.18-about-licenses.py index.html
import sys
p = sys.argv[1]; s = open(p, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    assert s.count(a) == n, (s.count(a), a[:90])
    s = s.replace(a, b)

rep("""  ['More', ['sound', 'keys', 'data', 'support']],""", """  ['More', ['sound', 'keys', 'data', 'support', 'about']],""")
rep("""sound: 'Intro and soundtrack', keys: 'Keyboard and gamepad', data: 'Setup Cloner, backup, restore', support: 'Keep MKCinema going',""",
    """sound: 'Intro and soundtrack', keys: 'Keyboard and gamepad', data: 'Setup Cloner, backup, restore', support: 'Keep MKCinema going',
  about: 'Version, credits, third-party licenses',""")

